<script setup lang="ts">
import { tx } from '@/i18n'
import { computed, onMounted, ref } from 'vue'
import { useAgentApi, useAgentActions, type CustomerAddress } from '../lib/agentWorkbench'
import { addressCities, addressCountries, addressRegions, withCurrentOption } from '../lib/addressCatalog'
const api = useAgentApi(), rows = ref<CustomerAddress[]>([]), editing = ref(false), editId = ref<number | null>(null), loading = ref(false)
const blank = () => ({ label: '', contactName: '', contactPhone: '', addressLine1: '', addressLine2: '', city: '', region: '', postalCode: '', country: '', defaultAddress: false })
const form = ref(blank()), { busy, error, success, run } = useAgentActions()
const addressDrawerOpen = computed({
  get: () => editing.value,
  set: value => { if (!value && !busy.value) editing.value = false },
})
async function load() { loading.value = true; try { rows.value = await api.fetchCustomerAddresses() } catch (e) { error.value = e instanceof Error ? e.message : tx('Unable to load addresses.') } finally { loading.value = false } }
function edit(row?: CustomerAddress) { editId.value = row?.id || null; form.value = row ? { label: row.label, contactName: row.contactName, contactPhone: row.contactPhone, addressLine1: row.addressLine1, addressLine2: row.addressLine2 || '', city: row.city, region: row.region || '', postalCode: row.postalCode, country: row.country, defaultAddress: row.defaultAddress } : blank(); editing.value = true }
async function save() { const payload = { ...form.value }; if (await run(`address:${editId.value || 'create'}`, payload, key => api.saveAddress(editId.value, payload, key), () => { editing.value = false }, tx('Sub-agent return address saved.'))) await load() }
onMounted(load)
</script>
<template><section data-testid="agent-addresses-panel"><div class="agent-toolbar"><h2>{{ $tx('Sub-agent return address') }}</h2><el-button type="primary" :disabled="busy" data-testid="agent-new-address" @click="edit()">{{ $tx('Add address') }}</el-button></div><p class="muted-copy">{{ $tx('After grading, NXR returns the entire batch to the selected sub-agent address.') }}</p><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="success" :title="success" type="success" :closable="false" /><p v-if="loading">{{ $tx('Loading…') }}</p><div v-else class="agent-address-list"><article v-for="row in rows" :key="row.id" class="agent-stock-card"><div class="agent-toolbar"><strong>{{ row.label }}{{ row.defaultAddress ? $tx(' · Default address') : '' }}</strong><el-button :disabled="busy" @click="edit(row)">{{ $tx('Edit') }}</el-button></div><p>{{ row.contactName }} · {{ row.contactPhone }}</p><p>{{ [row.country,row.region,row.city,row.addressLine1,row.addressLine2,row.postalCode].filter(Boolean).join(' · ') }}</p></article><el-empty v-if="!rows.length" :description="$tx('No sub-agent return addresses yet')" /></div><el-drawer v-model="addressDrawerOpen" :title="editId ? $tx('Edit return address') : $tx('Add return address')" size="min(720px, 96vw)" direction="rtl" destroy-on-close :close-on-click-modal="!busy" :show-close="!busy" data-testid="agent-address-drawer"><form v-if="editing" class="portal-form agent-operation" data-testid="agent-address-form" @submit.prevent="save"><div class="agent-toolbar"><h3>{{ editId ? $tx('Edit return address') : $tx('Add return address') }}</h3><el-button text :disabled="busy" @click="editing = false">{{ $tx('Cancel') }}</el-button></div><fieldset :disabled="busy"><label>{{ $tx('Address label') }}<input v-model="form.label" required maxlength="128" /></label><div class="form-grid"><label>{{ $tx('Recipient') }}<input v-model="form.contactName" required maxlength="128" /></label><label>{{ $tx('Phone number') }}<input v-model="form.contactPhone" required maxlength="64" /></label><label class="form-wide">{{ $tx('Address') }}<input v-model="form.addressLine1" required maxlength="255" /></label><label class="form-wide">{{ $tx('Address line 2') }}<input v-model="form.addressLine2" maxlength="255" /></label><label>{{ $tx('Country / region') }}<select v-model="form.country" required><option value="">{{ $tx('Choose country / region') }}</option><option v-for="option in withCurrentOption(addressCountries, form.country)" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label>{{ $tx('State / province') }}<select v-if="addressRegions(form.country).length" v-model="form.region" @change="form.city = ''"><option value="">{{ $tx('Choose region / state') }}</option><option v-for="option in withCurrentOption(addressRegions(form.country), form.region)" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-else v-model="form.region" maxlength="128" /></label><label>{{ $tx('City') }}<select v-if="addressCities(form.country, form.region).length" v-model="form.city" required><option value="">{{ $tx('Choose city') }}</option><option v-for="option in withCurrentOption(addressCities(form.country, form.region), form.city)" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-else v-model="form.city" required maxlength="128" /></label><label>{{ $tx('Postal code') }}<input v-model="form.postalCode" required maxlength="32" /></label></div><label class="agent-checkbox"><input v-model="form.defaultAddress" type="checkbox" />{{ $tx('Set as default address') }}</label></fieldset><button class="btn-primary" :disabled="busy" data-testid="agent-save-address">{{ $tx('Save address') }}</button></form></el-drawer></section></template>
